class NameTag {private final String firstName,lastName;public NameTag(String fullName){String[] parts=fullName.split(" ");firstName=parts[0];lastName=parts[1];}public String getNickname(){return firstName+" "+lastName.charAt(0)+".";}}
public class NicknameTag {public static void main(String[] args){NameTag tag=new NameTag("Maria Gomez");System.out.println(tag.getNickname());}}